{
  "root_causes": [
    {
      "service": "reservation",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, avg(value) AS avgv, min(value) AS minv, max(value) AS maxv, count(*) AS n FROM abnormal_metrics_sum WHERE metric='k8s.deployment.available' AND attr_k8s_deployment_name='reservation' GROUP BY ALL",
          "claim": "Reservation deployment reports 0 available replicas throughout the abnormal window, versus 1 in the normal period."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_container_name, attr_k8s_pod_name, count(*) AS n, min(value) AS minv, max(value) AS maxv FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'reservation%' GROUP BY ALL",
          "claim": "Reservation container restart counter climbs from 4 to 6 during the incident; the normal period shows zero restarts."
        },
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, c.span_name, count(*) AS n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) AS errs, avg(c.duration)/1e6 AS avg_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.span_name='reservation.Reservation/CheckAvailability' GROUP BY ALL",
          "claim": "Every frontend call to reservation.CheckAvailability errors out in about 0.015 ms (866 of 866), so no reservation work happens."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n FROM abnormal_traces WHERE service_name='reservation' GROUP BY ALL UNION ALL SELECT service_name, span_name, attr_span_kind, count(*) FROM normal_traces WHERE service_name='reservation' GROUP BY ALL",
          "claim": "Reservation's server and memcached spans are almost absent in the abnormal period (none) but present in normal (about 2000)."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "reservation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT s.span_name, s.attr_http_response_status_code AS status, count(*) AS n FROM abnormal_traces s WHERE s.service_name='frontend' AND s.attr_span_kind='Server' GROUP BY ALL ORDER BY n DESC",
          "claim": "Frontend HTTP /hotels returns 500 for 867 requests and /reservation for 9, while other routes return 200."
        }
      ]
    }
  ]
}
